// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type TriangularLogosProps = Record<string, any>;

const TriangularLogos: React.FC<TriangularLogosProps> = ({
  backgroundColor = "#f5f5f7",
  transparentBackground = false,
  durationInSeconds = 8,
  tiktokLogo = "https://upload.wikimedia.org/wikipedia/en/a/a9/TikTok_logo.svg",
  metaLogo = "https://upload.wikimedia.org/wikipedia/commons/7/7b/Meta_Platforms_Inc._logo.svg",
  googleLogo = "https://upload.wikimedia.org/wikipedia/commons/2/2f/Google_2015_logo.svg",
  rotationSpeed = 1,
  orbitRadiusMultiplier = 0.3,
  logoSizeMultiplier = 0.25,
  keepLogosUpright = true,
  showConnectingLines = true,
  lineColor = "#000000",
  titleText = "Global Networks",
  titleColor = "#111111",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors with string concatenation
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const s = Math.min(width, height);
  const orbitRadius = s * orbitRadiusMultiplier;
  const logoSize = s * logoSizeMultiplier;

  const logos = [tiktokLogo, metaLogo, googleLogo];

  const degreesToRotate = rotationSpeed * 360;
  const durationInFrames = Math.max(1, durationInSeconds * fps);
  
  // Interpolate rotation linearly over the duration
  const currentRotation = interpolate(
    frame,
    [0, durationInFrames],
    [0, degreesToRotate]
  );

  // Polygon connecting lines fade in smoothly
  const pathOpacity = interpolate(frame, [30, 60], [0, 0.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate coordinates for both the logos and the connecting SVG path
  const layout = logos.map((logo, index) => {
    // Offset by -90 degrees so the first logo starts at 12 o'clock
    const baseAngle = index * 120 - 90;
    const totalAngle = baseAngle + currentRotation;
    const angleInRadians = totalAngle * (Math.PI / 180);

    const x = Math.cos(angleInRadians) * orbitRadius;
    const y = Math.sin(angleInRadians) * orbitRadius;
    
    // Absolute canvas coordinates for SVG polygon
    const px = width / 2 + x;
    const py = height / 2 + y;

    return { logo, index, x, y, px, py, totalAngle };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill>
        
        {/* Render connecting triangle behind the logos */}
        {showConnectingLines && (
          <svg
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              left: 0,
              top: 0,
              overflow: "visible",
              opacity: pathOpacity,
              transition: "none",
            }}
          >
            <polygon
              points={layout.map((item) => `${item.px},${item.py}`).join(" ")}
              fill="none"
              stroke={lineColor}
              strokeWidth="4"
              strokeDasharray="15, 15"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ transition: "none" }}
            />
          </svg>
        )}

        {/* Render rotating logos */}
        {layout.map(({ logo, index, x, y, totalAngle }) => {
          const entranceScale = spring({
            frame: frame - index * 10, // stagger entrance
            fps,
            config: { damping: 12, mass: 0.8 },
          });

          // Allow the user to choose whether logos stay upright or rotate with the group
          const rotationOffset = keepLogosUpright ? 0 : totalAngle + 90;

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                width: logoSize,
                height: logoSize,
                // translate(-50%, -50%) centers the div element itself, then we animate along the radius
                transform: `translate(-50%, -50%) translate(${x}px, ${y}px) scale(${entranceScale}) rotate(${rotationOffset}deg)`,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transition: "none",
              }}
            >
              <Img
                src={logo}
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "contain",
                }}
              />
            </div>
          );
        })}

        {/* Title rendering */}
        {titleText && (
          <div
            style={{
              position: "absolute",
              top: height * 0.15,
              width: "100%",
              textAlign: "center",
              fontFamily: interFamily,
              fontSize: 64,
              fontWeight: "bold",
              color: titleColor,
              opacity: interpolate(frame, [0, 30], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              transform: `translateY(${interpolate(frame, [0, 30], [50, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })}px)`,
              transition: "none",
            }}
          >
            {titleText}
          </div>
        )}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default TriangularLogos;